-- 上外(sufe)必修一 情景闯关题(context_questions, grade=10, volume='required1', publisher='sufe')。Aaron 跑。幂等(只删 sufe 本册)。
BEGIN;
DELETE FROM public.context_questions WHERE publisher='sufe' AND volume='required1';

COMMIT;
SELECT unit, count(*) FROM public.context_questions WHERE publisher='sufe' AND volume='required1' GROUP BY unit ORDER BY unit;
SELECT count(*) AS context_q_sufe_required1 FROM public.context_questions WHERE publisher='sufe' AND volume='required1';
